class Retailer:
    def sell_masks(self, quantity: int) -> Tuple[int, bool]:
        quantity = int(max(0, min(self.rationing_policy, quantity)))
        if self.inventory_level <= 0:
            return 0, True
        sold = min(self.inventory_level, quantity)
        self.inventory_level -= sold
        shortage = self.inventory_level == 0  # signal stockout when hits zero
        return sold, shortage

def _retail_day(self, day: int) -> None:
    # Adjust prices by scarcity
    for r in self.retailers:
        r.adjust_prices()
    # Restock on schedule
    if day % self.restock_interval_days == 0:
        total_added = 0
        target = int(self.population_size * self.params.get("supply_initial_stock_per_capita", 2) / max(1, len(self.retailers)))
        remaining = self.restock_lot_size
        for r in self.retailers:
            added = r.restock_to_target(target, remaining)
            remaining -= added
            total_added += added
            if remaining <= 0:
                break
    # Stockout tracking and agent purchasing
    any_zero = any(r.inventory_level == 0 for r in self.retailers)
    if any_zero:
        self.metrics["mask_shortage_days"] = self.metrics.get("mask_shortage_days", 0) + 1
    # Agents with low inventory attempt to buy 1 mask
    for p in self.people.values():
        if p.masks_inventory <= 0:
            r = self.rng.choice(self.retailers)
            sold, stockout = r.sell_masks(1)
            p.masks_inventory += sold
            self.mask_price = r.price_per_mask

